const link=(path,label,cls='')=>`<a href="#${path}" class="${cls}">${label}</a>`;
const brand=()=>`<a class="brand" href="#/" aria-label="Изотоп РК — главная"><span class="brand-mark">И</span><span class="brand-text">ИЗОТОП РК<small>ИНЖЕНЕРИЯ · КОНТРОЛЬ</small></span></a>`;
const eyebrow=(text,light=false)=>`<span class="eyebrow${light?' light':''}">${text}</span>`;
const contactButton=(label,topic,cls='btn btn-primary')=>`<button type="button" class="${cls}" data-contact-open data-contact-topic="${topic}">${label}<span class="arrow">↗</span></button>`;
const arrowLink=(path,text)=>link(path,`${text} <span class="arrow">↗</span>`,'link-arrow');

function header(path){
  const active=path==='/services'||groups.some(g=>path===`/${g.key}`||path.startsWith(`/${g.key}/`));
  const mega=`<div class="mega-menu" id="services-mega" hidden><div class="container mega-inner"><div class="mega-intro"><span class="mono">КАРТА КОМПЕТЕНЦИЙ</span><h2>Одна команда для связанных технических задач</h2><p>От проектной идеи и измерений до приборов и документов.</p>${arrowLink('/services','Все услуги')}</div><div class="mega-groups">${groups.map(g=>`<div class="mega-group${g.featured?' featured':''}"><span>${g.lead}</span>${link(`/${g.key}`,g.title,'mega-title')}<div>${g.items.map(x=>link(x[1],x[0])).join('')}</div></div>`).join('')}</div></div></div>`;
  const mobile=`<nav class="mobile-nav" id="mobile-nav">${link('/','Главная')}<details><summary>Услуги <span>+</span></summary><div>${groups.map(g=>`<div class="mobile-group"><strong>${g.title}</strong>${g.items.map(x=>link(x[1],x[0])).join('')}</div>`).join('')}${link('/services','Все услуги →','mobile-all')}</div></details>${link('/about','О компании')}${link('/contacts','Контакты')}<div class="mobile-contact">${contactButton('Получить консультацию','Общая консультация')}</div></nav>`;
  return `<a class="skip-link" href="#main-content">Перейти к содержанию</a><div class="topbar"><div class="container"><span>МОСКВА · РАБОТАЕМ ПО ВСЕЙ РОССИИ</span><div class="topbar-right"><a href="tel:+74991413290">+7 (499) 141-32-90</a><a href="mailto:info@izotoprk.ru">info@izotoprk.ru</a></div></div></div><header class="site-header"><div class="container header-main">${brand()}<nav class="desktop-nav"><button class="nav-link nav-services${active?' active':''}" id="mega-toggle" aria-expanded="false" aria-controls="services-mega">Услуги <span>⌄</span></button>${link('/design','Проектирование','nav-link'+(path.startsWith('/design')?' active':''))}${link('/radiation','Радиационный контроль','nav-link'+(path.startsWith('/radiation')?' active':''))}${link('/about','О компании','nav-link'+(path==='/about'?' active':''))}${link('/contacts','Контакты','nav-link'+(path==='/contacts'?' active':''))}</nav>${contactButton('Получить консультацию','Общая консультация','btn btn-primary header-cta')}<button class="menu-button" id="menu-button" aria-label="Открыть меню" aria-expanded="false" aria-controls="mobile-nav"><span></span><span></span></button></div>${mega}${mobile}</header>`;
}

