function modal(){return `<dialog class="contact-modal" id="contact-modal" aria-labelledby="contact-modal-title"><div class="modal-shell"><button class="modal-close" data-modal-close aria-label="Закрыть">×</button><div class="modal-head">${eyebrow('БЫСТРАЯ СВЯЗЬ')}<h2 id="contact-modal-title">Обсудить задачу</h2><p>Выберите удобный канал или оставьте номер телефона.</p></div><div class="modal-topic"><span>Тема обращения</span><strong id="modal-topic">Общая консультация</strong></div><div class="messenger-grid">${['Telegram','WhatsApp','MAX'].map((x,i)=>`<button type="button" data-messenger="${x}"><span class="messenger-icon">${['TG','WA','MX'][i]}</span><strong>${x}</strong><small>Открыть диалог</small></button>`).join('')}</div><div class="modal-divider"><span>Или оставьте заявку</span></div><form class="modal-form" id="contact-form"><input type="hidden" id="modal-topic-input"><label><span>Ваше имя</span><input name="name" autocomplete="name" placeholder="Как к вам обращаться" required></label><label><span>Телефон</span><input name="phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="+7 ___ ___-__-__" required></label><label class="wide"><span>Кратко опишите задачу <em>необязательно</em></span><textarea placeholder="Объект, оборудование или направление"></textarea></label><button class="btn btn-primary wide" type="submit">Отправить заявку <span class="arrow">↗</span></button><p class="modal-note wide">Демонстрационная форма. Отправка будет подключена на этапе разработки.</p></form><div class="modal-success" id="modal-success" role="status" aria-live="polite" hidden><span>✓</span><h3 id="modal-success-title" tabindex="-1">Сценарий заявки показан</h3><p>В финальной версии обращение будет отправлено специалисту.</p><button class="btn btn-ghost" data-modal-close>Закрыть</button></div><div class="modal-toast" id="modal-toast" role="status" aria-live="polite"></div></div></dialog><div class="toast" id="prototype-toast" role="status" aria-live="polite"></div>`}

function crumbs(d,title){return `<div class="crumbs">${link('/','Главная')}<span>/</span>${d.parent?`${link(d.parent[0],d.parent[1])}<span>/</span>`:''}<span>${title}</span></div>`}
function pageHero(title,d){const special={'Все услуги':['00','КАРТА НАПРАВЛЕНИЙ'],'Проектирование':['01'],'Проектирование рентгеновских кабинетов':['02'],'Проектирование испытательных лабораторий':['03'],'Индивидуальный дозиметрический контроль':['04'],'Радиационный контроль':['05'],'Метрология':['06'],'Доставка оборудования':['07','ЛОГИСТИКА ОБОРУДОВАНИЯ'],'О компании':['RK','ПРОФИЛЬ КОМПАНИИ'],'Контакты':['→','СВЯЗЬ С КОМАНДОЙ']}[title]||[],index=special[0]||(d.level==='B'?'—':'•'),side=special[1]||'ТЕХНИЧЕСКОЕ НАПРАВЛЕНИЕ';return `<section class="page-hero"><div class="page-hero-grid"></div><div class="container">${crumbs(d,title)}<div class="page-hero-layout"><div>${eyebrow(`ИЗОТОП РК · ${d.label}`,true)}<h1>${title}</h1><p>${d.lead}</p><div class="hero-actions">${contactButton(d.cta,title,'btn btn-light')}${link('/services','Все услуги','btn btn-outline')}</div></div><div class="hero-index mono"><span>${index}</span><small>${side}</small></div></div></div></section>`}
function process(items,light=false){return `<div class="process${light?' process-light':''}">${items.map((x,i)=>`<div class="process-item"><span class="process-no">0${i+1} / 04</span><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div>`}
function technical(title,items){return `<div class="technical-sheet"><div class="sheet-top mono"><span>${title}</span><span>01—04</span></div>${items.map((x,i)=>`<div class="sheet-line"><span class="mono">0${i+1}</span><div><strong>${x}</strong><small>Уточняется под конкретную задачу</small></div></div>`).join('')}</div>`}
function relatedLinks(family){return `<div class="related-grid">${related[family].map((x,i)=>`<a href="#${x[1]}"><span class="mono">0${i+1}</span><strong>${x[0]}</strong><span class="arrow">↗</span></a>`).join('')}</div>`}
function finalCta(title='Обсудим вашу задачу',copy='Для первого разговора достаточно короткого описания объекта, оборудования или ожидаемого результата.',label='Связаться с нами',topic='Общая консультация'){return `<section class="final-cta"><div class="container final-cta-inner"><div>${eyebrow('СВЯЗАТЬСЯ С КОМАНДОЙ',true)}<h2>${title}</h2><p class="lead">${copy}</p></div><div class="final-contact-actions">${contactButton(label,topic,'btn btn-light')}<a class="final-phone" href="tel:+74991413290"><span class="mono">ИЛИ ПОЗВОНИТЕ</span><strong>+7 (499) 141-32-90</strong></a></div></div></section>`}

function home(){const rows=groups.map((g,i)=>`<a class="service-row${g.featured?' featured':''}" href="#/${g.key}"><span class="index-no">0${i+1}</span><h3>${g.title}</h3><p>${g.lead}. ${g.items.slice(0,2).map(x=>x[0]).join(', ')}.</p><span class="arrow">↗</span></a>`).join('');return `<main><section class="hero home-hero"><div class="hero-image"></div><div class="hero-shade"></div><div class="hero-blueprint"></div><div class="container hero-grid"><div class="hero-copy">${eyebrow('ИНЖЕНЕРИЯ РАДИАЦИОННОЙ БЕЗОПАСНОСТИ',true)}<h1>Технические задачи.<br><span class="accent">Одно решение.</span></h1><p class="hero-lead">Проектирование, дозиметрический и радиационный контроль, лабораторные направления и метрология — комплексно для организаций в Москве и по всей России.</p><div class="hero-actions">${link('/services','Изучить направления <span class="arrow">↗</span>','btn btn-light')}${contactButton('Обсудить решение','Комплексная задача','btn btn-outline')}</div></div></div><div class="hero-bottom"><div class="container"><div class="hero-proof"><span>01 / Инженерия</span>От проекта до контроля</div><div class="hero-proof"><span>02 / Масштаб</span>Москва и регионы</div><div class="hero-proof"><span>03 / Удобство</span>Доставка приборов</div></div></div></section><section class="section section-white"><div class="container"><div class="intro-grid"><div>${eyebrow('ОДНА КОМАНДА · СЕМЬ НАПРАВЛЕНИЙ')}<h2>Больше, чем отдельная услуга</h2></div><div><p class="lead">Радиационная безопасность объекта — связанная система: инженерия, измерения, персонал, документы и приборы.</p><p>Структура сайта помогает войти через конкретную задачу и увидеть весь маршрут.</p></div></div><div class="section-gap"></div><div class="service-index">${rows}</div></div></section><section class="feature-grid"><div class="feature-visual"><span class="visual-label mono">ПРОЕКТИРОВАНИЕ / ИНЖЕНЕРНЫЕ РЕШЕНИЯ</span></div><div class="feature-content">${eyebrow('КЛЮЧЕВОЕ НАПРАВЛЕНИЕ',true)}<h2>Проектирование как основа безопасной работы</h2><p>От назначения помещения и характеристик оборудования — к технически обоснованному решению.</p><div class="feature-points"><span>Рентгеновские кабинеты</span><span>Радиационные объекты</span><span>Испытательные лаборатории</span><span>Расчёт защиты</span></div>${link('/design','Смотреть проекты <span class="arrow">↗</span>','btn btn-light')}</div></section><section class="section section-pale"><div class="container split"><div>${eyebrow('ПЕРСОНАЛ · ДОЗИМЕТРИЯ')}<h2>Контроль доз — понятный регулярный процесс</h2><p class="lead">Организация контроля сотрудников, работающих с источниками излучения.</p>${arrowLink('/idk','Подробнее о контроле')}<div class="inline-cta">${contactButton('Обсудить контроль','Индивидуальный дозиметрический контроль','btn btn-ghost')}</div></div>${technical('ИДК / КОНТРОЛЬНЫЙ ЦИКЛ',['Состав персонала','Площадки и режим работ','Периодичность','Результаты'])}</div></section><section class="section section-white"><div class="container split"><div class="image-panel"><img src="./assets/metrology-lab.png" alt="Специалист выполняет измерения"><div class="image-panel-label"><span class="mono">ИЗМЕРЕНИЯ / ЛАБОРАТОРИЯ</span><h3>Точность начинается с правильного метода</h3></div></div><div>${eyebrow('КОНТРОЛЬ И ИЗМЕРЕНИЯ')}<h2>Фактические данные для технических решений</h2><p>Обследование объектов, помещений и рабочих мест.</p><ul class="bullet-list"><li>Радиационный контроль</li><li>Измерение физических факторов</li><li>Лабораторные работы</li></ul>${arrowLink('/radiation','Подробнее об измерениях')}</div></div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('СВЯЗАННЫЕ ЗАДАЧИ',true)}<h2>От вопроса до результата</h2></div><p class="text-white">Один проект может затрагивать несколько компетенций.</p></div>${process([['Контекст','Понимаем объект и ожидаемый результат.'],['Маршрут','Связываем направления и этапы.'],['Работы','Выполняем согласованный объём.'],['Результат','Передаём материалы и следующие шаги.']])}</div></section>${equipmentSection()}<section class="geo-band"><div class="container geo-inner"><div>${eyebrow('ГЕОГРАФИЯ РАБОТЫ')}<h2>Москва — точка контакта.<br>Россия — география задач.</h2><p>Для приборов можно согласовать курьерскую передачу, а формат региональных работ определяется под задачу.</p>${arrowLink('/delivery','Как устроена доставка')}</div>${geoGraphic()}</div></section><section class="section section-white"><div class="container trust-grid"><div>${eyebrow('ДОВЕРИЕ ЧЕРЕЗ ФАКТЫ')}<h2>Документы и компетенции — на виду</h2><p>В будущем сайте здесь появятся актуальные подтверждающие документы и области работ.</p><p class="page-note">Только проверенные материалы компании — без вымышленных номеров.</p></div><div class="trust-preview"><div class="document"><span class="mono">01 / ДОКУМЕНТЫ</span><strong>Подтверждения и области работ</strong></div><div class="document"><span class="mono">02 / КОМПЕТЕНЦИИ</span><strong>Направления лаборатории</strong></div></div></div></section>${finalCta()}</main>`}

