function geoGraphic(){return `<div class="geo-graphic"><i class="geo-dot a"></i><i class="geo-dot b"></i><i class="geo-dot c"></i><i class="geo-dot d"></i><i class="geo-dot e"></i><span class="geo-label">МОСКВА</span><span class="geo-caption">СХЕМА ГЕОГРАФИИ / НЕ КАРТА ПУНКТОВ ПРИЁМА</span></div>`}

function services(){return `<main>${pageHero('Все услуги',{label:'КАРТА КОМПЕТЕНЦИЙ',lead:'От проектирования специализированных объектов до измерений, документации и приборов.',cta:'Получить консультацию',level:'A'})}<section class="section section-white"><div class="container page-intro"><div>${eyebrow('ШИРОКИЙ ПРОФИЛЬ')}<h2>Задача клиента, а не формальное название услуги</h2></div><div><p class="lead">Направления собраны вокруг реальных сценариев: создать объект, организовать контроль, выполнить измерения или передать приборы.</p></div></div></section><section class="section section-pale"><div class="container catalog">${groups.map((g,i)=>`<article class="catalog-group${g.featured?' featured':''}"><span class="catalog-number mono">0${i+1}</span><div class="catalog-heading"><span>${g.lead}</span><h2>${g.title}</h2></div><div class="catalog-links">${g.items.map(x=>link(x[1],`${x[0]} <span class="arrow">↗</span>`)).join('')}</div></article>`).join('')}</div></section><section class="section section-white"><div class="container split"><div>${eyebrow('ПЕРВЫЙ РАЗГОВОР')}<h2>Не обязательно заранее выбирать раздел</h2><p class="lead">Опишите объект, оборудование и ожидаемый результат.</p>${contactButton('Получить консультацию','Подбор направления','btn btn-primary')}</div>${technical('ДОСТАТОЧНО ТРЁХ ПУНКТОВ',['Что за объект или прибор?','Где он находится?','Какой результат нужен?','На каком этапе задача?'])}</div></section>${finalCta('Задача на стыке направлений?','Расскажите о ней своими словами — точное название услуги определим вместе.','Обсудить решение','Комплексная задача')}</main>`}

function familyVisual(family){if(family==='project')return `<div class="family-visual project-family"><div class="blueprint-grid"></div><span class="mono">PROJECT DATA / REVIEW</span></div>`;if(family==='measurement')return `<div class="family-visual measure-family"><div class="measure-radar"><i></i><i></i><i></i></div><span class="mono">FIELD / CONTROL POINTS</span></div>`;if(family==='metrology')return `<div class="family-visual metrology-family"><div class="mini-device"><i></i><span class="mono">READY</span></div><span class="mono">INSTRUMENT / ROUTE</span></div>`;return `<div class="family-visual support-family"><div class="paper-stack"><i></i><i></i><i></i></div><span class="mono">DOCUMENT / PREPARATION</span></div>`}

function servicePage(path){const d=pages[path],title=routes[path];if(d.level==='B')return `<main class="light-service">${pageHero(title,d)}<section class="section section-white"><div class="container light-intro"><div><span class="family-tag mono">СТРАНИЦА НАПРАВЛЕНИЯ</span><h2>Задача и исходные данные</h2><p class="lead">${d.intro}</p>${contactButton(d.cta,title,'btn btn-primary')}</div>${familyVisual(d.family)}</div></section><section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('СОСТАВ РАБОТ')}<h2>Что учитывается</h2></div><p>Точный объём определяется после знакомства с объектом и материалами.</p></div><div class="compact-scope">${d.items.map((x,i)=>`<div><span class="mono">0${i+1}</span><strong>${x}</strong></div>`).join('')}</div></div></section><section class="section-sm section-white"><div class="container light-result"><div><span class="mono">ОЖИДАЕМЫЙ РЕЗУЛЬТАТ</span><h2>${d.result}</h2></div><div>${eyebrow('СВЯЗАННЫЕ НАПРАВЛЕНИЯ')}${relatedLinks(d.family)}</div></div></section>${finalCta('Обсудить эту услугу','Коротко опишите объект или оборудование.',d.cta,title)}</main>`;
  const project=d.family==='project',measure=d.family==='measurement',metro=d.family==='metrology';
  const visual=project?`<div class="project-blueprint"><div class="blueprint-grid"></div><span class="bp-room a">ОСНОВНАЯ ЗОНА</span><span class="bp-room b">ОБОРУДОВАНИЕ</span><span class="bp-room c">СМЕЖНАЯ ЗОНА</span><div class="bp-note mono">CONCEPT SCHEME<br>NOT FOR CONSTRUCTION</div></div>`:familyVisual(d.family);
  return `<main>${pageHero(title,d)}<section class="section section-white"><div class="container showcase-intro"><div>${eyebrow(project?'ОТ ИСХОДНЫХ ДАННЫХ К РЕШЕНИЮ':measure?'ФАКТИЧЕСКИЕ ДАННЫЕ':metro?'МАРШРУТ ОБОРУДОВАНИЯ':'СТРУКТУРА ЗАДАЧИ')}<h2>${d.intro}</h2><p class="lead">Каждый этап связан с конкретным результатом и следующими действиями заказчика.</p>${contactButton(d.cta,title,'btn btn-primary')}</div>${visual}</div></section><section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('ФОКУС НАПРАВЛЕНИЯ')}<h2>Что связывает работу</h2></div></div><div class="focus-grid">${d.items.map((x,i)=>`<article><span class="mono">0${i+1}</span><h3>${x}</h3><p>Состав и глубина проработки уточняются по исходным данным.</p></article>`).join('')}</div></div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('ПРОЦЕСС',true)}<h2>${project?'От схемы к комплекту материалов':metro?'От перечня до возврата':'От задачи до результата'}</h2></div></div>${process([['Исходные данные','Уточняем объект, оборудование и цель.'],['Подготовка','Формируем состав и порядок работ.'],['Выполнение','Работаем в согласованном объёме.'],['Результат','Передаём материалы и следующие шаги.']])}</div></section><section class="section section-white"><div class="container light-result"><div><span class="mono">РЕЗУЛЬТАТ</span><h2>${d.result}</h2></div><div>${eyebrow('СВЯЗАННЫЕ НАПРАВЛЕНИЯ')}${relatedLinks(d.family)}</div></div></section>${finalCta(project?'Есть объект для проектирования?':metro?'Подготовили перечень приборов?':'Нужен контроль или измерения?','Передайте исходные данные или коротко опишите задачу.',d.cta,title)}</main>`}

function delivery(){const d={label:'ЛОГИСТИКА ОБОРУДОВАНИЯ',lead:'Курьерская передача приборов для метрологических и связанных работ: по Москве и из регионов России.',cta:'Вызвать курьера',level:'A'};return `<main>${pageHero('Доставка оборудования',d)}<section class="section section-white"><div class="container delivery-hero"><div>${eyebrow('УДОБСТВО ДЛЯ ЗАКАЗЧИКА')}<h2>Оборудование может приехать к нам</h2><p class="lead">Маршрут, упаковка, комплектность и возврат согласуются до передачи.</p>${contactButton('Вызвать курьера','Курьерская доставка оборудования','btn btn-primary')}</div><div class="route-visual"><div class="route-point start"><span></span><strong>РЕГИОН</strong></div><div class="route-line"><i></i></div><div class="route-point finish"><span></span><strong>МОСКВА</strong></div><div class="route-case mono">EQUIPMENT<br>HANDLE WITH CARE</div></div></div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('ПОРЯДОК ПЕРЕДАЧИ',true)}<h2>От заявки до возврата</h2></div></div>${process([['Перечень','Модели, количество и комплектность.'],['Согласование','Адрес, упаковка и условия передачи.'],['Доставка','Передача по согласованной схеме.'],['Возврат','Приборы и документы заказчику.']])}</div></section><section class="section section-white"><div class="container split"><div>${eyebrow('ДО ОТПРАВКИ')}<h2>Что уточнить заранее</h2><ul class="bullet-list"><li>Модели и количество</li><li>Комплектность</li><li>Город отправления</li><li>Нужные работы</li></ul></div>${geoGraphic()}</div></section>${finalCta('Нужно передать приборы?','Сообщите модели оборудования и город отправления.','Вызвать курьера','Доставка оборудования')}</main>`}

function about(){const d={label:'КОМПАНИЯ',lead:'Технический партнёр для связанных задач в инженерии, контроле, лабораторных работах и метрологии.',cta:'Обсудить задачу',level:'A'};return `<main>${pageHero('О компании',d)}<section class="section section-white"><div class="container page-intro"><div>${eyebrow('ПОЗИЦИОНИРОВАНИЕ')}<h2>Широкий профиль. Один контекст задачи.</h2></div><div><p class="lead">Сила компании — в возможности рассматривать объект и процесс целиком.</p><p>Проектирование, персонал, измерения, документы и приборы часто пересекаются.</p></div></div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('ПРОФИЛЬ КОМПАНИИ',true)}<h2>Пять опорных компетенций</h2></div><p class="text-white">Без вымышленных цифр и рекламных обещаний.</p></div><div class="competence-line">${['Инженерия','Дозиметрия','Радиационный контроль','Лабораторные работы','Метрология'].map((x,i)=>`<div><span class="mono">0${i+1}</span><strong>${x}</strong></div>`).join('')}</div></div></section><section class="section section-white"><div class="container split"><div class="image-panel"><img src="./assets/engineering-plan.png" alt="Инженер работает с планом"><div class="image-panel-label"><span class="mono">ИНЖЕНЕРНЫЙ ПОДХОД</span><h3>От исходных данных к техническому решению</h3></div></div><div>${eyebrow('МОСКВА И ВСЯ РОССИЯ')}<h2>Близко к задаче, независимо от региона</h2><p>Компания находится в Москве и рассматривает проекты в регионах. Для приборов предусмотрена курьерская передача.</p><ul class="bullet-list"><li>Москва — место расположения</li><li>Региональные задачи — по всей России</li><li>Передача приборов — по согласованию</li></ul></div></div></section><section class="section section-pale"><div class="container trust-grid"><div>${eyebrow('ПРОВЕРЯЕМЫЕ СВЕДЕНИЯ')}<h2>Документы показываются предметно</h2><p>Финальный сайт должен содержать актуальные документы и подтверждённые области работ.</p><p class="page-note">Макет не подменяет их вымышленными номерами.</p></div><div class="trust-preview"><div class="document"><span class="mono">ДЛЯ ПУБЛИКАЦИИ</span><strong>Подтверждающие документы</strong></div><div class="document"><span class="mono">ДЛЯ ПУБЛИКАЦИИ</span><strong>Область работ</strong></div></div></div></section>${finalCta('Есть комплексная задача?','Опишите её без подбора точного названия услуги.','Обсудить решение','Комплексная задача')}</main>`}

function contacts(){const d={label:'СВЯЗЬ С КОМАНДОЙ',lead:'Для первого контакта достаточно короткого описания проекта, объекта или оборудования.',cta:'Связаться с нами',level:'A'};return `<main>${pageHero('Контакты',d)}<section class="section section-white"><div class="container contacts-grid"><div>${eyebrow('СВЯЗЬ С КОМПАНИЕЙ')}<h2>Начните с разговора</h2><div class="contact-item"><span class="mono">ТЕЛЕФОН</span><a href="tel:+74991413290">+7 (499) 141-32-90</a></div><div class="contact-item"><span class="mono">ПОЧТА</span><a href="mailto:info@izotoprk.ru">info@izotoprk.ru</a></div><div class="contact-item"><span class="mono">АДРЕС</span><strong>Москва, ул. Маршала Тимошенко, дом 23, строение 2</strong><p>Левое крыло, 2 этаж. Метро «Крылатское».</p></div><div class="contact-item"><span class="mono">ВРЕМЯ РАБОТЫ</span><strong>Пн–чт: 09:00–17:00 · Пт: 09:00–16:00</strong></div><div class="contact-channel-row">${['Telegram','WhatsApp','MAX'].map(x=>`<button data-messenger="${x}">${x}</button>`).join('')}</div>${contactButton('Связаться с нами','Обращение со страницы контактов','btn btn-primary')}</div><div class="contact-map"><div class="contact-map-pin"><strong>Изотоп РК</strong><small>ул. Маршала Тимошенко, 23, стр. 2</small></div><span class="mono">УСЛОВНАЯ СХЕМА · УТОЧНИТЕ МАРШРУТ</span></div></div></section><section class="section section-pale"><div class="container split"><div>${eyebrow('МОСКВА И РЕГИОНЫ')}<h2>Работаем с задачами по всей России</h2><p>Для оборудования можно обсудить курьерскую передачу.</p>${arrowLink('/delivery','Передача оборудования')}</div>${technical('ПЕРВОЕ ОБРАЩЕНИЕ',['Какая задача?','Где находится объект?','Какой результат нужен?','Как с вами связаться?'])}</div></section>${finalCta('Напишите или позвоните','Короткого описания достаточно для первого контакта.','Связаться с нами','Контакты')}</main>`}

/* Приоритетный контентный проход: ключевые страницы получают собственную композицию,
   а вторичные направления остаются на компактном общем шаблоне. */
function richTable(title,items){return `<div class="rich-table"><div class="rich-table-head mono"><span>${title}</span><span>ИЗОТОП РК</span></div>${items.map((x,i)=>`<div class="rich-table-row"><span class="mono">0${i+1}</span><div><strong>${x[0]}</strong><p>${x[1]}</p></div></div>`).join('')}</div>`}
function questionList(items){return `<div class="faq">${items.map(x=>`<details><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div>`}
function resultStrip(items){return `<div class="result-strip">${items.map((x,i)=>`<div><span class="mono">0${i+1}</span><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')}</div>`}
function serviceIntro(d,title,eyebrowText,heading,copy,visual){return `<main><section>${pageHero(title,d)}</section><section class="section section-white"><div class="container showcase-intro"><div>${eyebrow(eyebrowText)}<h2>${heading}</h2><p class="lead">${copy}</p>${contactButton(d.cta,title,'btn btn-primary')}</div>${visual}</div></section>`}
function projectBlueprint(label='ПЛАНИРОВОЧНАЯ ЛОГИКА'){return `<div class="project-blueprint"><div class="blueprint-grid"></div><span class="bp-room a">РАБОЧАЯ ЗОНА</span><span class="bp-room b">ОБОРУДОВАНИЕ</span><span class="bp-room c">СМЕЖНЫЕ ПОМЕЩЕНИЯ</span><div class="bp-note mono">${label}<br>СХЕМА ДЛЯ ОБСУЖДЕНИЯ</div></div>`}
function priorityServicePage(path){
  const d=pages[path],title=routes[path];
  if(path==='/design')return `${serviceIntro(d,title,'ПРОЕКТНАЯ ИНЖЕНЕРИЯ','Связываем объект, оборудование и будущий процесс','Проектирование начинается с понимания задачи: какое помещение создаётся, какое оборудование будет работать и какие документы понадобятся на следующем этапе.',projectBlueprint('PROJECT / INPUT DATA'))}<section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('КАК НАЧИНАЕТСЯ РАБОТА')}<h2>Сначала — исходные данные</h2></div><p>Чем точнее контекст, тем полезнее проектное решение для заказчика.</p></div>${resultStrip([['Объект','Назначение помещения и ограничения площадки.'],['Оборудование','Тип, параметры и размещение оборудования.'],['Процесс','Как будут проходить работы и кто использует зоны.'],['Документы','Какие материалы уже есть и что нужно подготовить.']])}</div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('ПРОЕКТНЫЙ МАРШРУТ',true)}<h2>От идеи к комплекту материалов</h2></div></div>${process([['Собираем контекст','Фиксируем назначение объекта, оборудование и ограничения.'],['Прорабатываем план','Связываем помещения, рабочие зоны и инженерные решения.'],['Сверяем решения','Проверяем взаимосвязь проектных разделов и исходных данных.'],['Передаём результат','Обсуждаем состав материалов и дальнейшие действия.']])}</div></section><section class="section section-white"><div class="container split"><div>${eyebrow('КЛЮЧЕВЫЕ НАПРАВЛЕНИЯ')}<h2>Проект можно продолжить связанными работами</h2><p class="lead">В зависимости от задачи к проектированию подключаются измерения, дозиметрический контроль, документация и работа с приборами.</p></div>${relatedLinks('project')}</div></section>${finalCta('Есть объект для проектирования?','Сообщите назначение помещения, оборудование и регион — начнём с состава исходных данных.','Согласовать проект',title)}</main>`;
  if(path==='/design/xray-cabinets')return `${serviceIntro(d,title,'РЕНТГЕНОВСКИЙ КАБИНЕТ','Проектируем кабинет как единую техническую систему','Планировка, оборудование, пультовая, смежные помещения и защитные решения должны быть согласованы между собой ещё до начала работ на объекте.',projectBlueprint('X-RAY ROOM / SCHEME'))}<section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('ЧТО НУЖНО УТОЧНИТЬ')}<h2>Контекст кабинета</h2></div><p>Перечень уточняется по конкретному объекту; ниже — основные точки первого разговора.</p></div>${richTable('ИСТОЧНИКИ ДЛЯ ПРОЕКТА',[['Помещение','План, размеры, назначение и соседние помещения.'],['Оборудование','Модель или технические параметры рентгеновской системы.'],['Рабочий процесс','Кто работает в кабинете и как организован доступ.'],['Защитные решения','Ограждения и конструктивные ограничения помещения.']])}</div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('СТАДИИ ПРОРАБОТКИ',true)}<h2>Важна последовательность решений</h2></div></div>${process([['Исходные данные','Собираем планировку, характеристики оборудования и режим работы.'],['Планировочная схема','Определяем кабинет, пультовую, входы и смежные зоны.'],['Техническая часть','Учитываем защитные и инженерные решения в составе задачи.'],['Документация','Формируем согласованный комплект для следующего этапа.']])}</div></section><section class="section section-white"><div class="container"><div class="section-heading"><div>${eyebrow('ВОПРОСЫ ЗАКАЗЧИКА')}<h2>До первого разговора</h2></div></div>${questionList([['Можно ли начать без полного комплекта документов?','Да, можно начать с описания объекта, планировки и сведений об оборудовании. Недостающие данные определим в ходе первого контакта.'],['Нужно ли учитывать соседние помещения?','Да. Состав смежных помещений и их назначение влияют на проектную задачу и должны быть обозначены заранее.'],['Работаете ли вы с регионами?','Компания находится в Москве и рассматривает задачи заказчиков из регионов по согласованному формату взаимодействия.']])}</div></section>${finalCta('Обсудить рентгеновский кабинет','Передайте план помещения и сведения об оборудовании — этого достаточно для первого обсуждения.','Согласовать проект',title)}</main>`;
  if(path==='/design/testing-laboratories')return `${serviceIntro(d,title,'ЛАБОРАТОРНАЯ ИНФРАСТРУКТУРА','Лаборатория начинается с будущего процесса','Проектная логика строится вокруг рабочих операций: какие исследования выполняются, как перемещаются образцы и где размещается оборудование.',projectBlueprint('LAB / WORKFLOW'))}<section class="section section-white"><div class="container"><div class="section-heading"><div>${eyebrow('ФУНКЦИОНАЛЬНАЯ СТРУКТУРА')}<h2>Пространство под реальные операции</h2></div><p>Планировка должна поддерживать процесс, а не просто заполнять помещение оборудованием.</p></div><div class="focus-grid"><article><span class="mono">01</span><h3>Потоки</h3><p>Разделяем рабочие маршруты, доступ и последовательность операций.</p></article><article><span class="mono">02</span><h3>Зоны</h3><p>Фиксируем назначение помещений и рабочих участков.</p></article><article><span class="mono">03</span><h3>Оборудование</h3><p>Учитываем габариты, размещение и связи между рабочими местами.</p></article><article><span class="mono">04</span><h3>Инженерия</h3><p>Сверяем проектные решения с требованиями будущей эксплуатации.</p></article></div></div></section><section class="section section-pale"><div class="container split"><div>${eyebrow('ИСТОЧНИКИ ДЛЯ СТАРТА')}<h2>Что полезно подготовить</h2><p class="lead">Описание задач лаборатории, перечень процессов, план помещения и предварительный список оборудования.</p>${contactButton('Обсудить проект','Проектирование испытательной лаборатории','btn btn-primary')}</div>${richTable('ПЕРВИЧНЫЙ КОМПЛЕКТ',[['Задачи','Какие исследования и испытания планируются.'],['Помещение','Площадь, планировка и ограничения объекта.'],['Оборудование','Состав, габариты и функциональные связи.'],['Результат','Какой формат проектных материалов нужен на выходе.']])}</div></section>${finalCta('Обсудить лабораторный проект','Расскажите, какие процессы должны работать в лаборатории и на каком этапе находится объект.','Согласовать проект',title)}</main>`;
  if(path==='/idk')return `${serviceIntro(d,title,'ПЕРСОНАЛ · ИДК','Регулярный контроль, встроенный в рабочий процесс','Индивидуальный дозиметрический контроль связывает сотрудников, места работы, периодичность и передачу результатов в одну понятную схему.',familyVisual('measurement'))}<section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('КОМУ НУЖЕН КОНТРОЛЬ')}<h2>Сценарий зависит от организации работ</h2></div><p>На старте важно описать персонал, площадки и характер контакта с источниками излучения.</p></div>${resultStrip([['Персонал','Кто включён в контроль и какие подразделения участвуют.'],['Рабочие места','На каких площадках и в каких зонах выполняются работы.'],['Периодичность','Как организован регулярный цикл и передача данных.'],['Результат','Какие сведения и документы нужны организации.']])}</div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('КОНТРОЛЬНЫЙ ЦИКЛ',true)}<h2>Понятный процесс для ответственного лица</h2></div></div>${process([['Состав персонала','Определяем участников и связанные рабочие места.'],['Организация цикла','Согласуем порядок и периодичность контроля.'],['Обработка данных','Результаты собираются в согласованном формате.'],['Передача','Организация получает материалы для дальнейшей работы.']])}</div></section><section class="section section-white"><div class="container split"><div>${eyebrow('СВЯЗАННЫЕ ЗАДАЧИ')}<h2>ИДК не существует отдельно от объекта</h2><p class="lead">При необходимости обсуждаются радиационный контроль рабочих зон, документация и другие связанные направления.</p></div>${relatedLinks('measurement')}</div></section>${finalCta('Обсудить индивидуальный контроль','Назовите организацию, площадки и примерный состав персонала.','Обсудить контроль',title)}</main>`;
  if(path==='/radiation')return `${serviceIntro(d,title,'РАДИАЦИОННЫЙ КОНТРОЛЬ','Измерения привязаны к объекту и цели','Состав работ зависит от того, что требуется проверить: помещение, рабочее место, оборудование или условия на объекте.',familyVisual('measurement'))}<section class="section section-white"><div class="container"><div class="section-heading"><div>${eyebrow('КОНТЕКСТ ИЗМЕРЕНИЙ')}<h2>Что именно контролируем</h2></div><p>Перед работой уточняется объект, доступ к нему и ожидаемый формат результата.</p></div><div class="focus-grid"><article><span class="mono">01</span><h3>Помещения</h3><p>Контроль рабочих и смежных зон, связанных с размещением оборудования.</p></article><article><span class="mono">02</span><h3>Рабочие места</h3><p>Измерения в точках, где сотрудники выполняют свои обязанности.</p></article><article><span class="mono">03</span><h3>Оборудование</h3><p>Обследование объектов и зон в связи с используемыми источниками.</p></article><article><span class="mono">04</span><h3>Физические факторы</h3><p>Состав определяется задачей и подтверждённой областью работ.</p></article></div></div></section><section class="section section-pale"><div class="container split"><div>${eyebrow('ПЕРЕД ВЫЕЗДОМ')}<h2>Полезно сообщить три вещи</h2><p class="lead">Где находится объект, что на нём размещено и для чего нужны измерения.</p>${contactButton('Обсудить измерения','Радиационный контроль','btn btn-primary')}</div>${richTable('ОРГАНИЗАЦИЯ РАБОТ',[['Объект','Адрес и назначение помещения или площадки.'],['Оборудование','Тип оборудования и его расположение.'],['Доступ','Условия проведения работ на территории.'],['Результат','Нужный состав материалов после измерений.']])}</div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('ПОЛЕВОЙ МАРШРУТ',true)}<h2>От точки измерения к понятному результату</h2></div></div>${process([['Цель','Уточняем, какое решение должно поддержать обследование.'],['Программа','Определяем объект и точки измерений.'],['Работа','Проводим обследование в согласованном объёме.'],['Материалы','Передаём результаты и обсуждаем следующие шаги.']])}</div></section>${finalCta('Обсудить радиационный контроль','Опишите объект и причину измерений — подскажем, какие исходные данные нужны.','Обсудить измерения',title)}</main>`;
  if(path==='/metrology')return `${serviceIntro(d,title,'МЕТРОЛОГИЯ · ПРИБОРЫ','Понятный маршрут для средств измерений','Сначала согласуем перечень и способ передачи оборудования, затем выполняются метрологические работы и оформляется возврат.',familyVisual('metrology'))}<section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('ЧТО НУЖНО ДЛЯ РАСЧЁТА')}<h2>Начните с перечня приборов</h2></div><p>Модель, количество, комплектность и город позволяют определить следующий шаг.</p></div>${richTable('ДАННЫЕ ОБ ОБОРУДОВАНИИ',[['Модель','Наименование и обозначение прибора.'],['Количество','Сколько единиц требуется передать в работу.'],['Комплектность','Что входит в комплект и в каком состоянии он передаётся.'],['Локация','Где находится оборудование и как его удобнее передать.']])}</div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('МАРШРУТ ОБОРУДОВАНИЯ',true)}<h2>От списка до возврата</h2></div></div>${process([['Перечень','Получаем модели, количество и контактные данные.'],['Передача','Согласуем самовывоз, курьерскую или иную схему.'],['Работы','Выполняем согласованный состав метрологических работ.'],['Возврат','Возвращаем приборы и документы в согласованном формате.']])}</div></section><section class="section section-white"><div class="container split"><div>${eyebrow('СВЯЗЬ С ДОСТАВКОЙ')}<h2>Регион не должен усложнять передачу</h2><p class="lead">Для оборудования из Москвы и регионов можно отдельно обсудить способ передачи и возврата.</p>${arrowLink('/delivery','Посмотреть маршрут оборудования')}</div>${relatedLinks('metrology')}</div></section>${finalCta('Передать оборудование','Сообщите модели приборов, количество и город — обсудим удобный порядок работы.','Передать оборудование',title)}</main>`;
  return `<main class="light-service">${pageHero(title,d)}<section class="section section-white"><div class="container light-intro"><div><span class="family-tag mono">СТРАНИЦА НАПРАВЛЕНИЯ</span><h2>${d.intro}</h2><p class="lead">Для первого обсуждения достаточно описания объекта, оборудования или комплекта документов.</p>${contactButton(d.cta,title,'btn btn-primary')}</div>${familyVisual(d.family)}</div></section><section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('СОСТАВ РАБОТ')}<h2>Что учитывается</h2></div><p>Точный объём определяется после знакомства с объектом и материалами.</p></div><div class="compact-scope">${d.items.map((x,i)=>`<div><span class="mono">0${i+1}</span><strong>${x}</strong></div>`).join('')}</div></div></section><section class="section-sm section-white"><div class="container light-result"><div><span class="mono">ОЖИДАЕМЫЙ РЕЗУЛЬТАТ</span><h2>${d.result}</h2></div><div>${eyebrow('СВЯЗАННЫЕ НАПРАВЛЕНИЯ')}${relatedLinks(d.family)}</div></div></section>${finalCta('Обсудить эту услугу','Коротко опишите объект, приборы или документы.',d.cta,title)}</main>`;
}

