function audience(title,text,items){return `<section class="section section-white"><div class="container explain-grid"><div>${eyebrow(title)}<h2>${text}</h2></div><ul class="bullet-list">${items.map(x=>`<li>${x}</li>`).join('')}</ul></div></section>`}
function deliverables(items){return `<div class="deliverable-grid">${items.map((x,i)=>`<div><span class="mono">0${i+1}</span><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')}</div>`}

function home(){const homeCopy={design:'Проектирование кабинетов, лабораторий и радиационных объектов с учётом оборудования и планировки.',idk:'Контроль индивидуальных доз сотрудников и организация регулярного мониторинга персонала.',radiation:'Измерения помещений, рабочих мест, оборудования и радиационной обстановки объекта.',laboratory:'Лабораторные и инженерно-экологические исследования, связанные с задачами объекта.',support:'Документы и материалы для проектирования, измерений и дальнейшего согласования.',metrology:'Поверка, диагностика, ремонт и передача дозиметров и приборов радиационного контроля.',delivery:'Согласованный маршрут передачи и возврата оборудования из Москвы и регионов.'};const rows=groups.map((g,i)=>`<a class="service-row${g.featured?' featured':''}" href="#/${g.key}"><span class="index-no">0${i+1}</span><h3>${g.title}</h3><p>${homeCopy[g.key]}</p><span class="arrow">↗</span></a>`).join('');return `<main><section class="hero home-hero"><div class="hero-image"></div><div class="hero-shade"></div><div class="hero-blueprint"></div><div class="container hero-grid"><div class="hero-copy">${eyebrow('ИНЖЕНЕРИЯ РАДИАЦИОННОЙ БЕЗОПАСНОСТИ',true)}<h1>Технические задачи.<br><span class="accent">Одно решение.</span></h1><p class="hero-lead">Проектирование, дозиметрический и радиационный контроль, лабораторные направления и метрология — для организаций в Москве и по всей России.</p><div class="hero-actions">${link('/services','Изучить направления <span class="arrow">↗</span>','btn btn-light')}${contactButton('Обсудить решение','Комплексная задача','btn btn-outline')}</div></div></div><div class="hero-bottom"><div class="container"><div class="hero-proof"><span>01 / Инженерия</span>От проекта до контроля</div><div class="hero-proof"><span>02 / Масштаб</span>Москва и регионы</div><div class="hero-proof"><span>03 / Удобство</span>Передача приборов</div></div></div></section><section class="section section-white"><div class="container"><div class="intro-grid"><div>${eyebrow('ОДНА КОМАНДА · СЕМЬ НАПРАВЛЕНИЙ')}<h2>Несколько связанных задач — один рабочий контекст</h2></div><div><p class="lead">Инженерия, измерения, персонал, документы и приборы часто нужны в одной цепочке.</p><p>Выберите направление или опишите задачу своими словами — маршрут можно собрать на первом разговоре.</p></div></div><div class="section-gap"></div><div class="service-index">${rows}</div></div></section><section class="feature-grid"><div class="feature-visual"><span class="visual-label mono">ПРОЕКТИРОВАНИЕ / ИНЖЕНЕРНЫЕ РЕШЕНИЯ</span></div><div class="feature-content">${eyebrow('КЛЮЧЕВОЕ НАПРАВЛЕНИЕ',true)}<h2>Проектирование как основа безопасной работы</h2><p>На старте важно связать назначение помещения, характеристики оборудования, рабочий процесс и документацию.</p><div class="feature-points"><span>Рентгеновские кабинеты</span><span>Радиационные объекты</span><span>Испытательные лаборатории</span><span>Расчёт радиационной защиты</span></div>${link('/design','Смотреть проекты <span class="arrow">↗</span>','btn btn-light')}</div></section><section class="section section-pale"><div class="container split"><div>${eyebrow('ПЕРСОНАЛ · ДОЗИМЕТРИЯ')}<h2>Контроль доз — понятный регулярный процесс</h2><p class="lead">ИДК помогает организации вести регулярный контроль сотрудников, работающих с источниками ионизирующего излучения.</p>${arrowLink('/idk','Подробнее о контроле')}<div class="inline-cta">${contactButton('Обсудить контроль','Индивидуальный дозиметрический контроль','btn btn-ghost')}</div></div>${technical('ИДК / КОНТРОЛЬНЫЙ ЦИКЛ',['Состав персонала','Площадки и режим работ','Периодичность','Передача результатов'])}</div></section><section class="section section-white"><div class="container split"><div class="image-panel"><img src="./assets/metrology-lab.png" alt="Специалист выполняет измерения"><div class="image-panel-label"><span class="mono">ИЗМЕРЕНИЯ / ЛАБОРАТОРИЯ</span><h3>Фактические данные для технических решений</h3></div></div><div>${eyebrow('КОНТРОЛЬ И ИЗМЕРЕНИЯ')}<h2>Радиационный контроль и измерение физических факторов</h2><p>Состав работ определяется объектом, условиями эксплуатации и целью контроля.</p><ul class="bullet-list"><li>Контроль помещений и рабочих зон</li><li>Обследование объектов и оборудования</li><li>Измерение физических факторов</li></ul>${arrowLink('/radiation','Подробнее об измерениях')}</div></div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('СВЯЗАННЫЕ ЗАДАЧИ',true)}<h2>От вопроса до результата</h2></div><p class="text-white">Один проект может затрагивать несколько компетенций — сайт помогает увидеть весь маршрут.</p></div>${process([['Контекст','Понимаем объект и ожидаемый результат.'],['Маршрут','Связываем направления и этапы.'],['Работы','Выполняем согласованный объём.'],['Результат','Передаём материалы и следующие шаги.']])}</div></section>${equipmentSection()}<section class="geo-band"><div class="container geo-inner"><div>${eyebrow('ГЕОГРАФИЯ РАБОТЫ')}<h2>Москва — точка контакта.<br>Россия — география задач.</h2><p>Для приборов можно согласовать передачу, а формат региональных работ определяется под задачу.</p>${arrowLink('/delivery','Как устроена доставка')}</div>${geoGraphic()}</div></section><section class="section section-white"><div class="container trust-grid"><div>${eyebrow('ДОВЕРИЕ ЧЕРЕЗ ФАКТЫ')}<h2>Документы и компетенции</h2><p>На сайте будут собраны актуальные подтверждающие документы и области работ компании.</p></div><div class="trust-preview"><div class="document"><span class="mono">01 / ДОКУМЕНТЫ</span><strong>Подтверждающие материалы</strong></div><div class="document"><span class="mono">02 / НАПРАВЛЕНИЯ</span><strong>Области работ и компетенции</strong></div></div></div></section>${finalCta()}</main>`}

function services(){return `<main>${pageHero('Все услуги',{label:'КАРТА КОМПЕТЕНЦИЙ',lead:'От проектирования специализированных объектов до измерений, документации и приборов.',cta:'Получить консультацию',level:'A'})}<section class="section section-white"><div class="container page-intro"><div>${eyebrow('ШИРОКИЙ ПРОФИЛЬ')}<h2>Каталог вокруг реальных задач</h2></div><div><p class="lead">Здесь можно понять, к какому направлению относится задача: создать или переоборудовать объект, организовать контроль, выполнить измерения, подготовить документы или передать приборы.</p><p>Если точное название неизвестно, достаточно описать объект и ожидаемый результат.</p></div></div></section><section class="section section-pale"><div class="container catalog">${groups.map((g,i)=>{const descriptions={design:'Проекты рентгеновских кабинетов, испытательных лабораторий и объектов с источниками излучения.',idk:'Индивидуальный контроль доз персонала и организация постоянного цикла наблюдений.',radiation:'Радиационный контроль помещений, рабочих мест, объектов и физических факторов.',laboratory:'Инженерно-экологические и лабораторные исследования в составе задачи заказчика.',support:'СЭЗ, технический паспорт кабинета и подготовка связанных материалов.',metrology:'Поверка, ремонт, диагностика и передача средств измерений.',delivery:'Организация передачи и возврата приборов из Москвы и регионов.'};return `<article class="catalog-group${g.featured?' featured':''}"><span class="catalog-number mono">0${i+1}</span><div class="catalog-heading"><span>${g.lead}</span><h2>${g.title}</h2><p>${descriptions[g.key]}</p></div><div class="catalog-links">${descriptiveLinks(g)}</div></article>`}).join('')}</div></section><section class="section section-white"><div class="container split"><div>${eyebrow('ПЕРВЫЙ РАЗГОВОР')}<h2>Не обязательно заранее выбирать раздел</h2><p class="lead">Опишите объект, оборудование и ожидаемый результат — это поможет начать предметно.</p>${contactButton('Получить консультацию','Подбор направления','btn btn-primary')}</div>${technical('ЧТО ПОЛЕЗНО СООБЩИТЬ',['Что за объект или прибор?','Где он находится?','Какой результат нужен?','Какие документы уже есть?'])}</div></section>${finalCta('Задача на стыке направлений?','Расскажите о ней своими словами — точное название услуги определим вместе.','Обсудить решение','Комплексная задача')}</main>`}

function priorityServicePage(path){const d=pages[path],title=routes[path];if(path==='/design')return `${serviceIntro(d,title,'ПРОЕКТНАЯ ИНЖЕНЕРИЯ','Проектирование связывает объект, оборудование и будущий процесс','ИЗОТОП РК на старом сайте описывает проектирование объектов капитального строительства, включая объекты использования атомной энергии и проекты размещения источников ионизирующего излучения. На практике заказчику важно заранее связать планировку, оборудование, защитные решения и состав проектных материалов.',projectBlueprint('PROJECT / INPUT DATA'))}${audience('КОМУ НУЖНО ПРОЕКТИРОВАНИЕ','Когда объект ещё создаётся, реконструируется или меняет оборудование',['медицинские организации и владельцы рентгеновских кабинетов','заказчики специализированных помещений и лабораторий','организации, которым нужно подготовить проектные решения для объекта с источниками излучения'])}<section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('ЧТО ВХОДИТ В ЗАДАЧУ')}<h2>Проект начинается не с чертежа</h2></div><p>Состав зависит от объекта, но исходная логика обычно строится вокруг четырёх вопросов.</p></div>${richTable('ИСХОДНЫЕ ДАННЫЕ',[['Объект','Назначение, планировка, этап строительства или реконструкции.'],['Оборудование','Тип, характеристики и предполагаемое размещение установок.'],['Процесс','Кто будет работать в помещениях и как будут перемещаться люди и материалы.'],['Документы','Имеющиеся планы, технические задания и результаты измерений.']])}</div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('ПРОЕКТНЫЕ РЕШЕНИЯ',true)}<h2>Специальные разделы связываются с общей документацией</h2></div><p class="text-white">На старом сайте компании отдельно указаны разделы по радиационной безопасности, радиационному контролю, расчёту радиационной защиты и другим специальным задачам.</p></div>${deliverables([['Радиационная безопасность','Материалы по организации безопасной эксплуатации объекта.'],['Радиационный контроль','Решения по контролю условий и параметров объекта.'],['Расчёт защиты','Расчётная часть, связанная с источником и планировкой.'],['Технологические решения','Связь оборудования и будущего процесса.']])}</div></section><section class="section section-white"><div class="container"><div class="section-heading"><div>${eyebrow('ЧТО ПОЛУЧАЕТ ЗАКАЗЧИК')}<h2>Не только набор файлов</h2></div></div>${questionList([['Можно ли начать, если полного задания ещё нет?','Да. Первый шаг — описать объект, оборудование и текущий этап. После этого можно определить недостающие исходные данные.'],['Связано ли проектирование с измерениями?','Да, в зависимости от задачи проект может опираться на результаты контроля объекта и дополняться связанными измерительными работами.'],['Можно ли заказать несколько направлений вместе?','Да, на первом разговоре можно рассмотреть проектирование, контроль, документы и работу с приборами как единую задачу.']])}</div></section>${finalCta('Обсудить проектирование','Назовите тип объекта, оборудование и регион — начнём с исходных данных.','Согласовать проект',title)}</main>`;
  if(path==='/design/xray-cabinets')return `${serviceIntro(d,title,'РЕНТГЕНОВСКИЙ КАБИНЕТ','Проект кабинета понятен ещё до начала работ','Проектирование рентгеновского кабинета — это согласование помещения, оборудования, пультовой, смежных зон и радиационно-защитных решений. Такой подход помогает не разрывать инженерную и документальную часть задачи.',projectBlueprint('X-RAY ROOM / SCHEME'))}${audience('КОМУ НУЖЕН ПРОЕКТ','Типичные ситуации заказчика',['открытие нового кабинета или медицинского подразделения','реконструкция помещения и замена рентгеновского оборудования','подготовка объекта к дальнейшим измерениям, паспорту и согласованию'])}<section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('ЧТО НУЖНО ПОДГОТОВИТЬ')}<h2>Пять исходных вопросов</h2></div><p>Часть данных можно собрать до первого разговора, остальное уточняется по ходу работы.</p></div>${richTable('ДАННЫЕ ДЛЯ ПРОЕКТА',[['Помещение','План, размеры, назначение и расположение смежных помещений.'],['Оборудование','Модель или технические характеристики рентгеновской системы.'],['Пультовая','Как организован контроль и рабочее место оператора.'],['Защитные конструкции','Состав ограждений и конструктивные ограничения помещения.'],['Документы','Имеющиеся планы, технические задания и результаты измерений.']])}</div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('ЭТАПЫ РАБОТЫ',true)}<h2>От помещения к согласованной схеме</h2></div></div>${process([['Собираем данные','Уточняем план, оборудование и назначение кабинета.'],['Размещаем зоны','Связываем процедурную, пультовую, входы и смежные помещения.'],['Прорабатываем защиту','Учитываем радиационно-защитные решения в связи с планировкой.'],['Готовим результат','Формируем состав материалов и обсуждаем следующие действия.']])}</div></section><section class="section section-white"><div class="container"><div class="section-heading"><div>${eyebrow('ПОСЛЕ ПРОЕКТА')}<h2>Какие связанные работы могут понадобиться</h2></div></div>${deliverables([['Радиационный контроль','Проверка условий и параметров помещения или оборудования.'],['Технический паспорт','Документирование кабинета и его технического оснащения.'],['СЭЗ','Подготовка и сопровождение материалов по конкретной задаче.'],['ИДК','Организация контроля персонала, если сотрудники работают с ИИИ.']])}</div></section><section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('ЧАСТЫЕ ВОПРОСЫ')}<h2>Что обычно уточняют владельцы кабинетов</h2></div></div>${questionList([['Что делать, если оборудование ещё не выбрано?','Можно начать с назначения кабинета и предполагаемого типа оборудования. Точные характеристики понадобятся для дальнейшей проработки.'],['Нужны ли смежные помещения на плане?','Да. Их назначение и расположение важны для понимания общей планировки и защитных решений.'],['Можно ли заказать проект и измерения в одной компании?','Да, эти направления можно обсудить вместе, если они относятся к одной задаче объекта.']])}</div></section>${finalCta('Обсудить рентгеновский кабинет','Передайте план помещения и сведения об оборудовании — этого достаточно для первого обсуждения.','Согласовать проект',title)}</main>`;
  if(path==='/design/testing-laboratories')return `${serviceIntro(d,title,'ЛАБОРАТОРНАЯ ИНФРАСТРУКТУРА','Лаборатория начинается с будущего процесса','Проект испытательной лаборатории должен объяснять не только, где стоит оборудование, но и как люди, образцы и рабочие операции проходят через пространство.',projectBlueprint('LAB / WORKFLOW'))}${audience('КОМУ НУЖЕН ТАКОЙ ПРОЕКТ','Когда лабораторное помещение нужно создать или перестроить',['организациям, которые планируют новые испытательные процессы','заказчикам, которым нужно увязать оборудование и функциональные зоны','проектам, где лаборатория является частью более крупного объекта'])}<section class="section section-white"><div class="container"><div class="section-heading"><div>${eyebrow('ПРОСТРАНСТВО ВОКРУГ РАБОТЫ')}<h2>Функциональная схема лаборатории</h2></div><p>Проектная логика отличается от рентгеновского кабинета: в центре — последовательность операций и связи между зонами.</p></div><div class="focus-grid"><article><span class="mono">01</span><h3>Потоки</h3><p>Как перемещаются сотрудники, образцы и материалы между этапами работы.</p></article><article><span class="mono">02</span><h3>Зоны</h3><p>Какие помещения и участки нужны для разных операций лаборатории.</p></article><article><span class="mono">03</span><h3>Оборудование</h3><p>Габариты, размещение, доступ и функциональные связи приборов.</p></article><article><span class="mono">04</span><h3>Инженерия</h3><p>Технические требования, которые нужно учитывать в проектных решениях.</p></article></div></div></section><section class="section section-pale"><div class="container split"><div>${eyebrow('ИСХОДНЫЕ ДАННЫЕ')}<h2>Что полезно описать до старта</h2><p class="lead">Какие исследования планируются, какие зоны уже есть, какое оборудование известно и какой результат нужен на выходе.</p>${contactButton('Обсудить проект','Проектирование испытательной лаборатории','btn btn-primary')}</div>${richTable('ПЕРВИЧНЫЙ КОМПЛЕКТ',[['Процессы','Какие исследования и испытания должны выполняться.'],['Помещение','Площадь, планировка и ограничения объекта.'],['Оборудование','Состав, габариты и функциональные связи.'],['Результат','Какой состав проектных материалов требуется.']])}</div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('РЕЗУЛЬТАТ ПРОЕКТА',true)}<h2>Пространство, которое поддерживает работу</h2></div></div>${process([['Сценарий','Фиксируем будущие операции и связи между ними.'],['Зонирование','Разделяем функциональные участки и маршруты.'],['Оборудование','Проверяем размещение и технические ограничения.'],['Материалы','Передаём согласованный состав проектной проработки.']])}</div></section>${finalCta('Обсудить лабораторный проект','Расскажите, какие процессы должны работать в лаборатории и на каком этапе находится объект.','Согласовать проект',title)}</main>`;
  if(path==='/idk')return `${serviceIntro(d,title,'ПЕРСОНАЛ · ИДК','Индивидуальный дозиметрический контроль простыми словами','ИДК — это измерение индивидуальной дозы персонала, работающего с источниками ионизирующего излучения. На старом сайте ИЗОТОП указано, что контроль проводится непрерывно, а снятие показаний и оформление протоколов организуется с установленной периодичностью.',familyVisual('measurement'))}${audience('КОМУ НУЖЕН ИДК','Организациям, где сотрудники работают с источниками излучения',['персоналу, который регулярно находится в зоне работы источников','организациям, которым нужно вести персональный, а не только объектовый контроль','ответственным за радиационную безопасность и учет результатов'])}<section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('КАК ОРГАНИЗУЕТСЯ ЦИКЛ')}<h2>Персонал, приборы и результаты</h2></div><p>Чтобы контроль был рабочим, заранее согласуются люди, площадки, периодичность и порядок передачи данных.</p></div>${richTable('КОНТРОЛЬНЫЙ ЦИКЛ',[['Состав персонала','Список сотрудников и рабочие функции, связанные с ИИИ.'],['Выдача приборов','Какие дозиметры используются и кому они передаются.'],['Снятие показаний','Периодичность и способ передачи приборов на обработку.'],['Протоколы','Оформление результатов для организации и ответственного лица.']])}</div></section><section class="section section-white"><div class="container split"><div>${eyebrow('ЧТО НУЖНО СООБЩИТЬ')}<h2>Начните с описания организации</h2><p class="lead">Полезно указать состав персонала, рабочие площадки, характер работ и текущий порядок контроля.</p>${contactButton('Обсудить контроль','Индивидуальный дозиметрический контроль','btn btn-primary')}</div>${deliverables([['Организация цикла','Понятная схема передачи приборов и данных.'],['Результаты','Оформленные материалы в согласованном составе.'],['Связанные работы','При необходимости — контроль объекта и документация.']])}</div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('ВОПРОСЫ ЗАКАЗЧИКА',true)}<h2>Что важно понять до начала</h2></div></div>${questionList([['Можно ли работать с регионом?','Да, формат взаимодействия с региональной организацией и передачей приборов обсуждается отдельно.'],['Что делать, если своих дозиметров не хватает?','На старом сайте компании указана возможность предоставления индивидуальных дозиметров во временное пользование — это необходимо подтвердить по конкретной задаче.'],['Связан ли ИДК с радиационным контролем помещений?','Это разные направления: ИДК относится к персоналу, а радиационный контроль — к объекту и условиям измерений. При необходимости их можно рассматривать вместе.']])}</div></section>${finalCta('Обсудить индивидуальный контроль','Назовите организацию, площадки и примерный состав персонала.','Обсудить контроль',title)}</main>`;
  if(path==='/radiation')return `${serviceIntro(d,title,'РАДИАЦИОННЫЙ КОНТРОЛЬ','Измерения привязаны к объекту и цели','Радиационный контроль помогает получить данные об индивидуальных и коллективных дозах, а также о радиационной обстановке. В составе работ ИЗОТОП также указывает измерение физических факторов.',familyVisual('measurement'))}${audience('КОГДА ЗАКАЗЫВАЮТ КОНТРОЛЬ','Когда нужно проверить условия на объекте или подтвердить фактические параметры',['при эксплуатации или изменении помещения с источниками излучения','при подготовке проектных, паспортных или санитарных материалов','для оценки условий рабочих мест и связанных помещений'])}<section class="section section-white"><div class="container"><div class="section-heading"><div>${eyebrow('ЧТО МОЖЕТ БЫТЬ ОБЪЕКТОМ')}<h2>Контроль начинается с точки измерения</h2></div><p>Конкретный состав определяется задачей и радиационной обстановкой организации.</p></div><div class="focus-grid"><article><span class="mono">01</span><h3>Помещения</h3><p>Рабочие и смежные зоны, связанные с размещением оборудования.</p></article><article><span class="mono">02</span><h3>Рабочие места</h3><p>Точки, где сотрудники выполняют работы и могут подвергаться воздействию.</p></article><article><span class="mono">03</span><h3>Оборудование</h3><p>Объекты и установки, для которых нужно оценить условия работы.</p></article><article><span class="mono">04</span><h3>Физические факторы</h3><p>Измерения факторов среды в составе производственного контроля.</p></article></div></div></section><section class="section section-pale"><div class="container split"><div>${eyebrow('ПЕРЕД ВЫЕЗДОМ')}<h2>Что сообщить специалисту</h2><p class="lead">Адрес и назначение объекта, оборудование, цель измерений и доступные документы помогут подготовить работу.</p>${contactButton('Обсудить измерения','Радиационный контроль','btn btn-primary')}</div>${richTable('ОРГАНИЗАЦИЯ',[['Объект','Где находятся помещения, рабочие места или оборудование.'],['Цель','Для эксплуатации, проекта, паспорта или другого результата.'],['Доступ','Когда и как специалист может попасть на объект.'],['Материалы','Какие планы, протоколы и документы уже есть.']])}</div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('ЧТО ПОЛУЧАЕТ ЗАКАЗЧИК',true)}<h2>Результат — не просто набор показаний</h2></div><p class="text-white">Данные используются для оценки обстановки, установления контрольных уровней и подготовки дальнейших решений, если это относится к задаче.</p></div>${deliverables([['Измерительные данные','Результаты по согласованным объектам и точкам.'],['Материалы контроля','Оформление в составе, определённом задачей.'],['Основа для решения','Данные для проекта, паспорта или дальнейших мероприятий.']])}</div></section><section class="section section-white"><div class="container"><div class="section-heading"><div>${eyebrow('ЧАСТЫЕ ВОПРОСЫ')}<h2>Перед первым обращением</h2></div></div>${questionList([['Можно ли измерить только одно помещение?','Да, состав объекта и объём работ можно обсудить отдельно.'],['Нужен ли готовый проект?','Не всегда. Сначала описывается цель измерений и имеющиеся материалы.'],['Можно ли объединить контроль и ИДК?','Да, если задача касается и условий на объекте, и контроля персонала.']])}</div></section>${finalCta('Обсудить радиационный контроль','Опишите объект и причину измерений — подскажем, какие исходные данные нужны.','Обсудить измерения',title)}</main>`;
  if(path==='/metrology')return `${serviceIntro(d,title,'МЕТРОЛОГИЯ · ПРИБОРЫ','Поверка — только один этап работы с прибором','В контексте ИЗОТОП метрологическая задача может включать поверку, диагностику, ремонт, настройку и передачу средств измерений. Сначала согласуется перечень приборов и их состояние, затем — маршрут оборудования.',familyVisual('metrology'))}${audience('КОМУ ПОДХОДИТ НАПРАВЛЕНИЕ','Организациям, у которых есть собственные приборы радиационного контроля',['предприятиям и учреждениям с парком дозиметров','медицинским и промышленным организациям, где нужны измерения','заказчикам из Москвы и регионов, которым нужно передать оборудование'])}<section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('ЧТО НУЖНО ДЛЯ РАСЧЁТА')}<h2>Начните с перечня приборов</h2></div><p>Модель, количество, комплектность и город позволяют определить следующий шаг.</p></div>${richTable('ДАННЫЕ ОБ ОБОРУДОВАНИИ',[['Модель','Наименование и обозначение прибора.'],['Количество','Сколько единиц требуется передать в работу.'],['Состояние','Работает ли прибор, нужен ли ремонт или диагностика.'],['Комплектность','Что входит в комплект и как оборудование будет передаваться.'],['Город','Где находится оборудование и как его удобнее доставить.']])}</div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('МАРШРУТ ОБОРУДОВАНИЯ',true)}<h2>От списка до возврата</h2></div></div>${process([['Перечень','Получаем модели, количество и контактные данные.'],['Проверка задачи','Уточняем поверку, диагностику, ремонт или настройку.'],['Передача','Согласуем доставку, курьерскую или другую схему.'],['Возврат','Возвращаем приборы и оформленные материалы.']])}</div></section><section class="section section-white"><div class="container split"><div>${eyebrow('ЧТО ПОЛУЧАЕТ ЗАКАЗЧИК')}<h2>Результат зависит от согласованного состава работ</h2><p class="lead">Это может быть поверка, документы по результатам, диагностика или ремонт — точный состав фиксируется до передачи оборудования.</p>${arrowLink('/delivery','Посмотреть маршрут оборудования')}</div>${deliverables([['Поверка','Работа со средствами измерений по согласованной задаче.'],['Диагностика и ремонт','Если прибор требует проверки состояния или настройки.'],['Передача','Организованный маршрут оборудования и документов.']])}</div></section><section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('ВОПРОСЫ ЗАКАЗЧИКА')}<h2>Что уточнить заранее</h2></div></div>${questionList([['Как передать приборы из региона?','Можно отдельно обсудить курьерскую или другую согласованную схему передачи и возврата.'],['Можно ли заказать ремонт вместе с поверкой?','Да, если состояние прибора требует дополнительных работ; это уточняется после описания оборудования.'],['Что отправить первым сообщением?','Модель, количество, город и короткое описание задачи.']])}</div></section>${finalCta('Передать оборудование','Сообщите модели приборов, количество и город — обсудим удобный порядок работы.','Передать оборудование',title)}</main>`;
  return `<main class="light-service">${pageHero(title,d)}<section class="section section-white"><div class="container light-intro"><div><span class="family-tag mono">СТРАНИЦА НАПРАВЛЕНИЯ</span><h2>${d.intro}</h2><p class="lead">Для первого обсуждения достаточно описания объекта, приборов или комплекта документов.</p>${contactButton(d.cta,title,'btn btn-primary')}</div>${familyVisual(d.family)}</div></section><section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('СОСТАВ РАБОТ')}<h2>Что учитывается</h2></div><p>Точный объём определяется после знакомства с объектом и материалами.</p></div><div class="compact-scope">${d.items.map((x,i)=>`<div><span class="mono">0${i+1}</span><strong>${x}</strong></div>`).join('')}</div></div></section><section class="section-sm section-white"><div class="container light-result"><div><span class="mono">ОЖИДАЕМЫЙ РЕЗУЛЬТАТ</span><h2>${d.result}</h2></div><div>${eyebrow('СВЯЗАННЫЕ НАПРАВЛЕНИЯ')}${relatedLinks(d.family)}</div></div></section>${finalCta('Обсудить эту услугу','Коротко опишите объект, приборы или документы.',d.cta,title)}</main>`;
}

function about(){const d={label:'КОМПАНИЯ',lead:'Технический партнёр для связанных задач в инженерии, контроле, лабораторных работах и метрологии.',cta:'Обсудить задачу',level:'A'};return `<main>${pageHero('О компании',d)}<section class="section section-white"><div class="container page-intro"><div>${eyebrow('КТО ТАКОЙ ИЗОТОП РК')}<h2>Профиль компании — на стыке инженерии и контроля</h2></div><div><p class="lead">На официальном сайте ИЗОТОП РК компания описывает работу с радиационным контролем, дозиметрией, проектированием, лабораторными направлениями и метрологией.</p><p>Это не отдельные несвязанные услуги: для одного объекта могут последовательно понадобиться проект, измерения, документы и работа с приборами.</p></div></div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('ОСНОВНЫЕ НАПРАВЛЕНИЯ',true)}<h2>Компетенции, которые соединяются в задаче</h2></div><p class="text-white">Позиционирование основано на направлениях, перечисленных на текущем сайте компании.</p></div><div class="competence-line">${[['01','Проектирование'],['02','ИДК персонала'],['03','Радиационный контроль'],['04','Лабораторные работы'],['05','Метрология']].map(x=>`<div><span class="mono">${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div></div></section><section class="section section-white"><div class="container split"><div class="image-panel"><img src="./assets/engineering-plan.png" alt="Инженер работает с планом"><div class="image-panel-label"><span class="mono">ИНЖЕНЕРНЫЙ ПОДХОД</span><h3>От исходных данных к техническому решению</h3></div></div><div>${eyebrow('ЧТО ДЕЛАЕТ КОМПАНИЯ')}<h2>От объекта и персонала до приборов и документов</h2><p>На старом сайте отдельно описаны проектирование радиационных источников и рентгеновских кабинетов, ИДК, радиационный контроль, поверка и ремонт дозиметров, а также инженерно-экологические и лабораторные работы.</p><ul class="bullet-list"><li>Проектная и инженерная проработка объектов</li><li>Контроль персонала, помещений и физических факторов</li><li>Работа со средствами измерений</li><li>Подготовка связанных документов</li></ul></div></div></section><section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('МОСКВА И РОССИЯ')}<h2>Один контакт для московских и региональных задач</h2></div><p>Компания указана на старом сайте по московскому адресу; формат региональной работы и передачи приборов согласуется под конкретную задачу.</p></div>${deliverables([['Москва','Основная точка контакта компании.'],['Регионы','Задачи за пределами Москвы рассматриваются отдельно.'],['Оборудование','Передачу и возврат приборов можно обсудить заранее.']])}</div></section><section class="section section-white"><div class="container trust-grid"><div>${eyebrow('ДОКУМЕНТЫ И КОМПЕТЕНЦИИ')}<h2>Подтверждение должно быть предметным</h2><p>На финальной версии сайта следует разместить только актуальные лицензии, аккредитации, области работ и документы, подтверждённые компанией.</p></div><div class="trust-preview"><div class="document"><span class="mono">01 / ДОКУМЕНТЫ</span><strong>Лицензии и подтверждения</strong></div><div class="document"><span class="mono">02 / ОБЛАСТИ РАБОТ</span><strong>Актуальный состав компетенций</strong></div></div></div></section>${finalCta('Есть комплексная задача?','Опишите её без подбора точного названия услуги — начнём с контекста.','Обсудить решение','Комплексная задача')}</main>`}

function supplementaryService(path){const d=pages[path],title=routes[path];if(path==='/laboratory')return `<main>${pageHero(title,d)}<section class="section section-white"><div class="container showcase-intro"><div>${eyebrow('ИССЛЕДОВАНИЯ И ИСПЫТАНИЯ')}<h2>Лабораторные работы начинаются с вопроса, который нужно проверить</h2><p class="lead">На старом сайте ИЗОТОП указаны инженерно-экологические и санитарно-экологические исследования, а также лаборатория неразрушающего контроля. Конкретный состав зависит от объекта и подтверждённой области работ.</p>${contactButton('Обсудить исследования',title,'btn btn-primary')}</div>${familyVisual('measurement')}</div></section><section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('КОГДА ОБРАЩАЮТСЯ')}<h2>От объекта к программе работ</h2></div><p>Перед началом важно определить, что исследуется и какой результат нужен организации.</p></div>${richTable('ИСТОЧНИКИ ДЛЯ ОБСУЖДЕНИЯ',[['Объект','Помещение, строительные материалы, конструкция или территория.'],['Задача','Что нужно измерить, проверить или зафиксировать.'],['Доступ','Где и когда можно провести работы.'],['Результат','Протокол, отчёт или другой согласованный комплект материалов.']])}</div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('ПОРЯДОК РАБОТЫ',true)}<h2>Измерения должны отвечать на конкретный вопрос</h2></div></div>${process([['Цель','Уточняем объект и вопрос заказчика.'],['Программа','Определяем состав и порядок работ.'],['Исследование','Проводим согласованные измерения или испытания.'],['Материалы','Оформляем результат в согласованном составе.']])}</div></section>${finalCta('Обсудить лабораторную задачу','Опишите объект, что нужно проверить и какой документ требуется на выходе.','Обсудить исследования',title)}</main>`;return `<main>${pageHero(title,d)}<section class="section section-white"><div class="container light-intro"><div>${eyebrow('ДОКУМЕНТЫ И ПОДГОТОВКА')}<h2>Связанные материалы для специализированного объекта</h2><p class="lead">Сопровождение помогает собрать проектные, измерительные и организационные материалы в понятный комплект.</p>${contactButton(d.cta,title,'btn btn-primary')}</div>${familyVisual('support')}</div></section><section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('ЧТО МОЖЕТ ВХОДИТЬ')}<h2>Документ зависит от задачи</h2></div><p>На старом сайте ИЗОТОП отдельно представлены СЭЗ и технический паспорт рентгеновского кабинета.</p></div>${richTable('НАПРАВЛЕНИЯ',[['СЭЗ','Подготовка материалов, связанных с санитарно-эпидемиологическим заключением.'],['Паспорт кабинета','Документирование технического оснащения рентгеновского кабинета.'],['Измерения','Результаты контроля, которые могут понадобиться в составе задачи.'],['Проект','Исходные и проектные материалы для специализированного объекта.']])}</div></section><section class="section section-white"><div class="container"><div class="section-heading"><div>${eyebrow('КАК НАЧАТЬ')}<h2>Соберите то, что уже есть</h2></div></div>${resultStrip([['Объект','Что оформляется и где он находится.'],['Документы','Какие планы, протоколы и проекты уже готовы.'],['Цель','Для эксплуатации, проекта или дальнейшего согласования.'],['Следующий шаг','Какой результат нужен организации.']])}</div></section>${finalCta('Обсудить документы','Назовите объект и документ, который требуется подготовить или проверить.','Обсудить документы',title)}</main>`}
function getPage(path){if(path==='/')return home();if(path==='/services')return services();if(path==='/delivery')return delivery();if(path==='/about')return about();if(path==='/contacts')return contacts();if(path==='/laboratory'||path==='/support')return supplementaryService(path);return priorityServicePage(path)}

function setup(){
  const menu=document.getElementById('mobile-nav'),menuBtn=document.getElementById('menu-button'),mega=document.getElementById('services-mega'),megaBtn=document.getElementById('mega-toggle'),dlg=document.getElementById('contact-modal'),form=document.getElementById('contact-form'),success=document.getElementById('modal-success'),toast=document.getElementById('prototype-toast');
  menuBtn.onclick=()=>{const open=menu.classList.toggle('open');menuBtn.classList.toggle('open',open);menuBtn.setAttribute('aria-expanded',open);menuBtn.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню')};
  menu.querySelectorAll('a').forEach(a=>a.onclick=()=>{menu.classList.remove('open');menuBtn.classList.remove('open');menuBtn.setAttribute('aria-expanded','false');menuBtn.setAttribute('aria-label','Открыть меню')});
  const closeMega=()=>{mega.hidden=true;megaBtn.setAttribute('aria-expanded','false')};
  megaBtn.onclick=e=>{e.stopPropagation();mega.hidden=!mega.hidden;megaBtn.setAttribute('aria-expanded',!mega.hidden)};
  document.onclick=e=>{if(!mega.hidden&&!mega.contains(e.target)&&e.target!==megaBtn)closeMega()};
  document.onkeydown=e=>{if(e.key==='Escape'&&!mega.hidden){closeMega();megaBtn.focus()}};
  document.querySelectorAll('[data-contact-open]').forEach(b=>b.onclick=()=>{const topic=b.dataset.contactTopic;form.reset();document.getElementById('modal-topic').textContent=topic;document.getElementById('modal-topic-input').value=topic;document.querySelectorAll('.toast,.modal-toast').forEach(t=>t.classList.remove('visible'));form.hidden=false;success.hidden=true;dlg.showModal();dlg.querySelector('input[name=name]').focus()});
  document.querySelectorAll('[data-modal-close]').forEach(b=>b.onclick=()=>dlg.close());dlg.onclick=e=>{if(e.target===dlg)dlg.close()};
  const showToast=(x,inside)=>{const target=inside?document.getElementById('modal-toast'):toast,other=inside?toast:document.getElementById('modal-toast');clearTimeout(target._timer);clearTimeout(other._timer);other.classList.remove('visible');target.textContent=`${x} будет подключён на этапе разработки сайта.`;target.classList.add('visible');target._timer=setTimeout(()=>target.classList.remove('visible'),3000)};
  document.querySelectorAll('[data-messenger]').forEach(b=>b.onclick=()=>showToast(b.dataset.messenger,Boolean(b.closest('dialog'))));
  form.onsubmit=e=>{e.preventDefault();form.hidden=true;success.hidden=false;document.getElementById('modal-success-title').focus()};
}

function render(){const requested=location.hash.slice(1)||'/',path=routes[requested]?requested:'/';document.title=`${routes[path]} — Изотоп РК · концепт`;document.getElementById('app').innerHTML=header(path)+getPage(path)+footer()+modal();const main=document.querySelector('main');main.id='main-content';main.tabIndex=-1;setup();scrollTo(0,0);main.focus({preventScroll:true})}
addEventListener('hashchange',render);render();

/* Финальная редактура клиентского текста: сайт говорит от лица компании. */
function clientCopy(html){return html
  .replace(/На официальном сайте ИЗОТОП РК компания описывает работу с радиационным контролем, дозиметрией, проектированием, лабораторными направлениями и метрологией\./g,'ИЗОТОП РК выполняет работы в области радиационного контроля, индивидуальной дозиметрии, проектирования, лабораторных исследований и метрологии.')
  .replace(/Позиционирование основано на направлениях, перечисленных на текущем сайте компании\./g,'Компетенции компании объединяют проектирование, контроль, лабораторные работы и метрологию.')
  .replace(/На старом сайте отдельно описаны/g,'Компания выполняет')
  .replace(/Компания указана на старом сайте по московскому адресу;/g,'Основная точка контакта компании находится в Москве;')
  .replace(/На старом сайте ИЗОТОП указано, что контроль проводится непрерывно, а снятие показаний и оформление протоколов организуется с установленной периодичностью\./g,'Контроль проводится регулярно: персонал работает с индивидуальными дозиметрами, а показания и протоколы оформляются с установленной периодичностью.')
  .replace(/На старом сайте компании указана возможность предоставления индивидуальных дозиметров во временное пользование — это необходимо подтвердить по конкретной задаче\./g,'При необходимости можно отдельно обсудить предоставление индивидуальных дозиметров во временное пользование.')
  .replace(/На старом сайте ИЗОТОП указаны инженерно-экологические и санитарно-экологические исследования, а также лаборатория неразрушающего контроля\./g,'Компания выполняет инженерно-экологические и санитарно-экологические исследования, а также лабораторные работы неразрушающего контроля.')
  .replace(/На старом сайте ИЗОТОП отдельно представлены СЭЗ и технический паспорт рентгеновского кабинета\./g,'В направлении выделяются санитарно-эпидемиологическое заключение и технический паспорт рентгеновского кабинета.')
  .replace(/Компания указывает собственную лабораторную базу, склад запасных частей и штат экспертов, которые могут выезжать на объект заказчика\./g,'Компания располагает собственной лабораторной базой, складом запасных частей и штатом экспертов, которые выезжают на объект заказчика.')
  .replace(/Актуальный комплект разрешительных документов и областей работ предоставляется компанией для публикации после проверки\./g,'Комплект разрешительных документов и областей работ формируется по конкретным видам работ.')
  .replace(/После подключения формы обращение будет передано специалисту\./g,'Специалист свяжется с вами по указанным контактам.')
  .replace(/Специалист свяжется с вами после подключения формы\./g,'Специалист свяжется с вами по указанным контактам.')
  .replace(/В будущем сайте здесь появятся актуальные подтверждающие документы и области работ компании\./g,'На странице собраны направления и документы, которые компания готова подтвердить и опубликовать.')
  .replace(/Только проверенные материалы компании — без вымышленных номеров\./g,'Публикуются только актуальные документы и подтверждённые области работ.')
  .replace(/Без вымышленных цифр и рекламных обещаний\./g,'Факты и документы компании')
  .replace(/Макет не подменяет их вымышленными номерами\./g,'Актуальный состав документов подтверждается компанией перед публикацией.')
  .replace(/<span class="prototype-badge">ПРЕЗЕНТАЦИОННЫЙ ПРОТОТИП<\/span>/g,'');}

function about(){const d={label:'КОМПАНИЯ',lead:'Многопрофильная организация в области радиационного контроля, дозиметрии, проектирования, лабораторных исследований и метрологии.',cta:'Обсудить задачу',level:'A'};return `<main>${pageHero('О компании',d)}<section class="section section-white"><div class="container page-intro"><div>${eyebrow('КТО МЫ')}<h2>ИЗОТОП РК — специализированная техническая компания</h2></div><div><p class="lead">Компания основана в 2002 году и прошла путь от аналитического центра до многопрофильной организации.</p><p>Сегодня ИЗОТОП РК объединяет инженерные, измерительные, лабораторные и метрологические направления вокруг задач заказчика.</p></div></div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('ОСНОВНЫЕ НАПРАВЛЕНИЯ',true)}<h2>Компетенции, которые соединяются в одной задаче</h2></div><p class="text-white">Работа компании охватывает объект, персонал, оборудование и документы.</p></div><div class="competence-line">${[['01','Радиационный контроль'],['02','Индивидуальная дозиметрия'],['03','Проектирование комплексов'],['04','Испытательная лаборатория'],['05','Метрология и ремонт']].map(x=>`<div><span class="mono">${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div></div></section><section class="section section-white"><div class="container split"><div class="image-panel"><img src="./assets/engineering-plan.png" alt="Инженер работает с планом"><div class="image-panel-label"><span class="mono">ИНЖЕНЕРНЫЙ ПОДХОД</span><h3>От исходных данных к техническому решению</h3></div></div><div>${eyebrow('ЧЕМ ЗАНИМАЕТСЯ КОМПАНИЯ')}<h2>От проектирования объекта до работы с прибором</h2><p>ИЗОТОП РК проектирует рентгеновские кабинеты и другие специализированные комплексы, выполняет радиационный и дозиметрический контроль, проводит лабораторно-инструментальные исследования, поверяет и ремонтирует дозиметры.</p><ul class="bullet-list"><li>Проектирование медицинских комплексов и объектов с источниками излучения</li><li>Радиационный контроль и измерение физических факторов</li><li>Инженерно-экологические исследования</li><li>Поверка, диагностика и ремонт средств измерений</li></ul></div></div></section><section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('ОПЫТ И ТЕХНИЧЕСКАЯ БАЗА')}<h2>Работаем своими специалистами и оборудованием</h2></div><p>Компания указывает собственную лабораторную базу, склад запасных частей и штат экспертов, которые могут выезжать на объект заказчика.</p></div>${deliverables([['Лаборатория','Лабораторно-инструментальные измерения и исследования объектов.'],['Метрология','Поверка, калибровка, диагностика и ремонт дозиметров.'],['Эксперты','Специалисты выезжают на объект и проводят согласованные работы.'],['Оборудование','Приборы и техническая база для измерительных задач.']])}</div></section><section class="section section-white"><div class="container"><div class="section-heading"><div>${eyebrow('КТО ОБРАЩАЕТСЯ')}<h2>Задачи разных отраслей</h2></div><p>Компания работает с организациями, которым нужно контролировать условия, оборудование или проектную документацию.</p></div><div class="focus-grid"><article><span class="mono">01</span><h3>Медицина</h3><p>Рентгеновские кабинеты, медицинские комплексы и контроль оборудования.</p></article><article><span class="mono">02</span><h3>Промышленность</h3><p>Предприятия, производственные площадки и задачи радиационного контроля.</p></article><article><span class="mono">03</span><h3>Банки и организации</h3><p>Поверка и обслуживание дозиметрического оборудования.</p></article><article><span class="mono">04</span><h3>Строительство</h3><p>Инженерно-экологические исследования и проектные задачи.</p></article></div></div></section><section class="section section-dark"><div class="container"><div class="section-heading"><div>${eyebrow('ПОДТВЕРЖДЕНИЕ КОМПЕТЕНЦИЙ',true)}<h2>Лицензии, аккредитации и документы</h2></div><p class="text-white">Актуальный комплект разрешительных документов и областей работ предоставляется компанией для публикации после проверки.</p></div>${deliverables([['Лицензии','Документы на виды деятельности, которые требуют разрешения.'],['Аккредитации','Подтверждения компетенций лабораторных и измерительных направлений.'],['Области работ','Актуальный перечень выполняемых задач.'],['Документы','Материалы, которые заказчик может проверить.']])}</div></section><section class="section section-pale"><div class="container"><div class="section-heading"><div>${eyebrow('МОСКВА И РОССИЯ')}<h2>Основная точка контакта — Москва</h2></div><p>Компания рассматривает задачи из регионов России. Для приборов можно заранее согласовать передачу и возврат оборудования.</p></div>${deliverables([['Москва','ул. Маршала Тимошенко, дом 23, строение 2.'],['Регионы','Выездные и дистанционные форматы обсуждаются под задачу.'],['Приборы','Передача оборудования согласуется до начала работ.']])}</div></section>${finalCta('Обсудим вашу задачу','Опишите объект, оборудование или документ — подскажем, с какого направления начать.','Обсудить решение','Комплексная задача')}</main>`}

function modal(){return `<dialog class="contact-modal" id="contact-modal" aria-labelledby="contact-modal-title"><div class="modal-shell"><button class="modal-close" data-modal-close aria-label="Закрыть">×</button><div class="modal-head">${eyebrow('БЫСТРАЯ СВЯЗЬ')}<h2 id="contact-modal-title">Обсудить задачу</h2><p>Выберите удобный канал или оставьте номер телефона.</p></div><div class="modal-topic"><span>Тема обращения</span><strong id="modal-topic">Общая консультация</strong></div><div class="messenger-grid">${['Telegram','WhatsApp','MAX'].map((x,i)=>`<button type="button" data-messenger="${x}"><span class="messenger-icon">${['TG','WA','MX'][i]}</span><strong>${x}</strong><small>Открыть диалог</small></button>`).join('')}</div><div class="modal-divider"><span>Или оставьте заявку</span></div><form class="modal-form" id="contact-form"><input type="hidden" id="modal-topic-input"><label><span>Ваше имя</span><input name="name" autocomplete="name" placeholder="Как к вам обращаться" required></label><label><span>Телефон</span><input name="phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="+7 ___ ___-__-__" required></label><label class="wide"><span>Кратко опишите задачу <em>необязательно</em></span><textarea placeholder="Объект, оборудование или направление"></textarea></label><button class="btn btn-primary wide" type="submit">Отправить заявку <span class="arrow">↗</span></button><p class="modal-note wide">После подключения формы обращение будет передано специалисту.</p></form><div class="modal-success" id="modal-success" role="status" aria-live="polite" hidden><span>✓</span><h3 id="modal-success-title" tabindex="-1">Заявка принята</h3><p>Специалист свяжется с вами после подключения формы.</p><button class="btn btn-ghost" data-modal-close>Закрыть</button></div><div class="modal-toast" id="modal-toast" role="status" aria-live="polite"></div></div></dialog><div class="toast" id="prototype-toast" role="status" aria-live="polite"></div>`}

function render(){const requested=location.hash.slice(1)||'/',path=routes[requested]?requested:'/';document.title=`${routes[path]} — Изотоп РК`;document.getElementById('app').innerHTML=clientCopy(header(path)+getPage(path)+footer()+modal());const main=document.querySelector('main');main.id='main-content';main.tabIndex=-1;setup();scrollTo(0,0);main.focus({preventScroll:true})}

/* Визуальная редактура страницы «О компании»: фоновые сцены и маршрут компетенций. */
function aboutRouteMarkup(){
  let html=about();
  html=html.replace('<section class="section section-pale"><div class="container"><div class="section-heading"><div><span class="eyebrow">ОПЫТ И ТЕХНИЧЕСКАЯ БАЗА</span>', '<section class="section section-pale about-tech-section"><div class="about-section-image" aria-hidden="true"></div><div class="container about-section-layer"><div class="section-heading"><div><span class="eyebrow">ОПЫТ И ТЕХНИЧЕСКАЯ БАЗА</span>');
  html=html.replace('<p>Компания указывает собственную лабораторную базу, склад запасных частей и штат экспертов, которые могут выезжать на объект заказчика.</p>', '<p>Компания располагает собственной лабораторной базой, складом запасных частей и штатом экспертов, которые выезжают на объект заказчика.</p>');
  html=html.replace('<div class="focus-grid"><article><span class="mono">01</span><h3>Медицина</h3>', '<div class="focus-grid about-industries-grid"><article class="industry-card industry-card--medicine"><span class="mono">01</span><h3>Медицина</h3>');
  html=html.replace('<article><span class="mono">02</span><h3>Промышленность</h3>', '<article class="industry-card industry-card--industry"><span class="mono">02</span><h3>Промышленность</h3>');
  html=html.replace('<article><span class="mono">03</span><h3>Банки и организации</h3>', '<article class="industry-card industry-card--metrology"><span class="mono">03</span><h3>Банки и организации</h3>');
  html=html.replace('<article><span class="mono">04</span><h3>Строительство</h3>', '<article class="industry-card industry-card--construction"><span class="mono">04</span><h3>Строительство</h3>');
  const route='<div class="competence-route" aria-label="Маршрут компетенций">'+[['01','Радиационный контроль','объект и среда'],['02','Индивидуальная дозиметрия','персонал и режим работ'],['03','Проектирование комплексов','помещение и оборудование'],['04','Испытательная лаборатория','исследования и измерения'],['05','Метрология и ремонт','приборы и результат']].map(x=>`<div class="route-stop"><span class="route-node">${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('')+'</div>';
  html=html.replace(/<div class="competence-line">[\s\S]*?<\/div><\/div><\/section>/, route+'</div></section>');
  return html;
}
function getPage(path){if(path==='/')return home();if(path==='/services')return services();if(path==='/delivery')return delivery();if(path==='/about')return aboutRouteMarkup();if(path==='/contacts')return contacts();if(path==='/laboratory'||path==='/support')return supplementaryService(path);return priorityServicePage(path)}
render();

/* Дополнительная нормализация текста на внутренних страницах. */
function researchCopy(html){return clientCopy(html)
  .replace(/ИЗОТОП РК на старом сайте описывает проектирование объектов капитального строительства, включая объекты использования атомной энергии и проекты размещения источников ионизирующего излучения\./g,'ИЗОТОП РК проектирует объекты капитального строительства, включая объекты использования атомной энергии и проекты размещения источников ионизирующего излучения.')
  .replace(/На старом сайте компании отдельно указаны разделы по радиационной безопасности, радиационному контролю, расчёту радиационной защиты и другим специальным задачам\./g,'Проектные решения включают разделы по радиационной безопасности, радиационному контролю, расчёту радиационной защиты и другим специальным задачам.')
  .replace(/На старом сайте отдельно описаны проектирование радиационных источников и рентгеновских кабинетов, ИДК, радиационный контроль, поверка и ремонт дозиметров, а также инженерно-экологические и лабораторные работы\./g,'ИЗОТОП РК выполняет проектирование радиационных источников и рентгеновских кабинетов, ИДК, радиационный контроль, поверку и ремонт дозиметров, а также инженерно-экологические и лабораторные работы.')}
function render(){const requested=location.hash.slice(1)||'/',path=routes[requested]?requested:'/';document.title=`${routes[path]} — Изотоп РК`;document.getElementById('app').innerHTML=researchCopy(header(path)+getPage(path)+footer()+modal());const main=document.querySelector('main');main.id='main-content';main.tabIndex=-1;setup();scrollTo(0,0);main.focus({preventScroll:true})}
render();
